// Exports the puzzle solutions that live in the Python half of the repo
// (../advent_of_code and ../project_euler) as JSON the puzzles page fetches at runtime,
// the same way process-markdown.js does for the blog.
//
//   src/assets/puzzles/index.json            what exists and what is solved
//   src/assets/puzzles/aoc/<year>/<NN>.json  one Advent of Code day: source + per-part status
//   src/assets/puzzles/euler/<NNN>.json      one Project Euler problem: source
//
// The output is derived entirely from those directories, so it is gitignored and
// regenerated by `npm run prebuild`; it is wiped first so deleted solutions disappear.

const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.join(__dirname, '..', '..');
const AOC_DIR = path.join(REPO_ROOT, 'advent_of_code');
const EULER_DIR = path.join(REPO_ROOT, 'project_euler');
const OUTPUT_DIR = path.join(__dirname, '..', 'src', 'assets', 'puzzles');

// Project Euler only permits publishing solutions to the first hundred problems.
const EULER_PUBLISH_LIMIT = 100;

// Advent of Code ran 25 puzzles a year until 2024, and 12 from 2025 on.
const aocDaysInYear = (year) => (year >= 2025 ? 12 : 25);

/**
 * The 1-based [start, end] lines of a top-level `def name(...)`, or null if absent.
 * The body runs until the next line of code at column zero. Blank lines, comments
 * (commented-out test inputs often sit at column zero mid-function) and the insides
 * of triple-quoted strings don't end it.
 */
function functionSpan(lines, name) {
  const defPattern = new RegExp(`^def ${name}\\s*\\(`);
  const start = lines.findIndex((line) => defPattern.test(line));
  if (start === -1) return null;

  let end = start;
  let openQuote = null;
  for (let i = start + 1; i < lines.length; i++) {
    const line = lines[i];
    const wasInString = openQuote !== null;
    for (const quote of line.match(/"""|'''/g) ?? []) {
      if (openQuote === null) openQuote = quote;
      else if (openQuote === quote) openQuote = null;
    }
    if (wasInString) {
      end = i;
      continue;
    }
    if (line.trim() === '' || line.startsWith('#')) continue;
    if (!/^\s/.test(line)) break;
    end = i;
  }
  return { startLine: start + 1, endLine: end + 1 };
}

/**
 * Whether a function has a real body, rather than the template's `pass`.
 * Blank lines, comments, docstrings, `pass`, `...` and a bare `return` don't count.
 */
function isImplemented(lines, span) {
  if (!span) return false;
  const body = lines
    .slice(span.startLine, span.endLine)
    .join('\n')
    .replace(/("""|''')[\s\S]*?\1/g, '')
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line !== '' && !line.startsWith('#'))
    .filter((line) => !['pass', '...', 'return', 'return None'].includes(line));
  return body.length > 0;
}

/**
 * Splits off a module docstring, if the file opens with one. Its first line is the
 * title, any further paragraphs are a short write-up shown above the code, and the
 * code is what follows it, with `lineOffset` the number of lines removed from the top
 * (so function spans can be shifted to match).
 */
function splitDocstring(source) {
  const match = source.match(/^\s*("""|''')([\s\S]*?)\1[^\n]*\n?/);
  if (!match) return { title: null, description: null, code: source, lineOffset: 0 };

  const [firstLine, ...rest] = match[2].trim().split('\n');
  const title = firstLine.trim();
  const description = rest.join('\n').trim();

  let code = source.slice(match[0].length);
  const leadingBlank = code.match(/^(\s*\n)*/)[0];
  code = code.slice(leadingBlank.length);
  const lineOffset = (match[0] + leadingBlank).split('\n').length - 1;

  return {
    // The template's placeholder docstring isn't a title.
    title: title && !title.startsWith('<') ? title : null,
    description: description || null,
    code,
    lineOffset,
  };
}

function listFiles(dir, pattern) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .map((name) => ({ name, match: name.match(pattern) }))
    .filter(({ match }) => match)
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
}

function writeJson(relativePath, data) {
  const outputPath = path.join(OUTPUT_DIR, relativePath);
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, JSON.stringify(data, null, 2) + '\n');
}

function exportAdventOfCode() {
  const years = [];

  for (const { name: yearDir, match } of listFiles(AOC_DIR, /^y(\d{4})$/)) {
    const year = parseInt(match[1], 10);
    const totalDays = aocDaysInYear(year);
    const solutions = [];

    for (const { name: file, match: dayMatch } of listFiles(
      path.join(AOC_DIR, yearDir),
      /^day_(\d{2})\.py$/,
    )) {
      const day = parseInt(dayMatch[1], 10);
      if (day < 1 || day > totalDays) {
        console.warn(`Skipping ${yearDir}/${file}: ${year} only has ${totalDays} days`);
        continue;
      }

      const source = fs.readFileSync(path.join(AOC_DIR, yearDir, file), 'utf-8');
      const lines = source.split('\n');
      const parts = [1, 2].map((part) => {
        const span = functionSpan(lines, `part_${part}`);
        return { part, solved: isImplemented(lines, span), ...(span ?? {}) };
      });
      const stars = parts.filter((p) => p.solved).length;
      if (stars === 0) continue;

      const { title, description, code, lineOffset } = splitDocstring(source);
      writeJson(`aoc/${year}/${String(day).padStart(2, '0')}.json`, {
        year,
        day,
        title,
        description,
        stars,
        parts: parts.map((p) =>
          p.startLine
            ? { ...p, startLine: p.startLine - lineOffset, endLine: p.endLine - lineOffset }
            : p,
        ),
        problemUrl: `https://adventofcode.com/${year}/day/${day}`,
        source: code,
      });
      solutions.push({ day, stars, title });
    }

    if (solutions.length > 0) {
      years.push({ year, totalDays, solutions });
    }
  }

  years.sort((a, b) => b.year - a.year);
  return { years };
}

function exportProjectEuler() {
  const solved = [];

  for (const { name: file, match } of listFiles(EULER_DIR, /^problem_(\d{3,})\.py$/)) {
    const problem = parseInt(match[1], 10);
    if (problem > EULER_PUBLISH_LIMIT) continue;

    const source = fs.readFileSync(path.join(EULER_DIR, file), 'utf-8');
    const lines = source.split('\n');
    if (!isImplemented(lines, functionSpan(lines, 'solve'))) continue;

    const { title, description, code } = splitDocstring(source);
    writeJson(`euler/${String(problem).padStart(3, '0')}.json`, {
      problem,
      title,
      description,
      problemUrl: `https://projecteuler.net/problem=${problem}`,
      source: code,
    });
    solved.push({ problem, title });
  }

  return { publishLimit: EULER_PUBLISH_LIMIT, solved };
}

fs.rmSync(OUTPUT_DIR, { recursive: true, force: true });

const index = { aoc: exportAdventOfCode(), euler: exportProjectEuler() };
writeJson('index.json', index);

const aocDays = index.aoc.years.reduce((n, y) => n + y.solutions.length, 0);
const aocStars = index.aoc.years.reduce(
  (n, y) => n + y.solutions.reduce((m, s) => m + s.stars, 0),
  0,
);
console.log(
  `Puzzles: ${aocDays} Advent of Code days (${aocStars} stars) across ` +
    `${index.aoc.years.length} years, ${index.euler.solved.length} Project Euler problems`,
);
